<?php declare(strict_types=1);use StudPulse\Bars\AcademicWatch;use StudPulse\Database\DB;use StudPulse\Domain\Reminders;use StudPulse\Integrations\WebPush;use StudPulse\Integrations\MpeiMailConnections;use StudPulse\Integrations\{MpeiMailCache,MpeiMailbox};use StudPulse\Integrations\DriveSync;use StudPulse\Integrations\DriveSyncWorker;use StudPulse\Http\ApiError;if(PHP_SAPI!=='cli'){http_response_code(404);exit(1);}$timestamp=static fn():string=>(new DateTimeImmutable('now',new DateTimeZone('Europe/Moscow')))->format('d.m.Y H:i:s');$stage='подключение к MySQL';$locked=false;$exit=0;try{require_once dirname(__DIR__).'/app/bootstrap.php';DriveSyncWorker::requireRuntime();$locked=(bool)DB::one("SELECT GET_LOCK('studpulse:notifications',0) AS acquired")['acquired'];if(!$locked){printf("[%s] Проверка уже выполняется другим экземпляром.\n",$timestamp());}else{$stage='проверка напоминаний';printf("[%s] Проверяю дедлайны и журнал…\n",$timestamp());$reminders=Reminders::collect();printf("[%s] Новых напоминаний: %d. Проверяю обновления БАРС…\n",$timestamp(),$reminders);$academic=0;try{$report=(new AcademicWatch())->poll();$academic=$report['checked'];printf("[%s] БАРС · успешно %d из %d · в очереди %d · старейшая ждёт %d мин\n",$timestamp(),$academic,$report['attempted'],$report['remaining'],$report['oldestMinutes']);}catch(Throwable$error){fwrite(STDERR,"[{$timestamp()}] Ошибка проверки БАРС (".get_class($error).")\n");$exit=1;}if(\StudPulse\Config::bool('MPEI_MAIL_ENABLED')){try{printf("[%s] Почта МЭИ · новых уведомлений: %d\n",$timestamp(),MpeiMailConnections::poll());}catch(Throwable$error){fwrite(STDERR,"[{$timestamp()}] Ошибка проверки почты МЭИ (".get_class($error).")\n");$exit=1;}}$stage='отправка Web Push';printf("[%s] Отправляю Web Push…\n",$timestamp());$push=WebPush::deliverPending();printf("[%s] Успешных проверок БАРС: %d · Push принят сервисом: %d (почта: %d) · Подписок к отправке: %d (почта: %d) · Истекло: %d · Ошибок доставки: %d\n",$timestamp(),(int)$academic,$push['sent'],$push['mailSent'],$push['candidates'],$push['mailCandidates'],$push['expired'],$push['failed']);if(!$push['mailSchema'])fwrite(STDERR,"[{$timestamp()}] Web Push · нужна миграция bin/migrate.php для отдельной доставки почты.\n");foreach($push['errors']as$code=>$count){fprintf(STDERR,"[%s] Web Push · %s · подписок: %d\n",$timestamp(),$code,$count);}$exit=max($exit,(int)($push['failed']>0));}}catch(ApiError$error){fwrite(STDERR,"[{$timestamp()}] {$error->getMessage()} PHP: ".PHP_BINARY."\n");$exit=1;}catch(Throwable$error){fwrite(STDERR,"[{$timestamp()}] Сбой на этапе «{$stage}» (".get_class($error).")\n");$exit=1;}finally{if($locked)DB::run("SELECT RELEASE_LOCK('studpulse:notifications')");}if($locked){try{$run=DriveSync::tick();if($run){printf("[%s] Библиотека · %s · %s · %s%s · восстановлено: %d · ошибок восстановления: %d\n",$timestamp(),$run['id'],$run['stage'],$run['status'],$run['error_code']?' · '.$run['error_code']:'',$run['progress']['repaired']??0,$run['progress']['repair_failed']??0);if(!empty($run['error']['message']))fwrite(STDERR,$run['error']['message']."\n");if($run['status']==='failed')$exit=1;if($exit===0&&($argv[1]??'')==='--worker'&&$run['status']==='paused'&&!$run['error_code'])$exit=75;}}catch(Throwable$error){fwrite(STDERR,"[{$timestamp()}] Сбой синхронизации библиотеки (".get_class($error).")\n");$exit=1;}if(MpeiMailbox::available()&&microtime(true)-($_SERVER['REQUEST_TIME_FLOAT']??microtime(true))<47){try{MpeiMailCache::worker();}catch(ApiError$error){if($error->errorCode!=='MPEI_MAIL_BUSY'){fprintf(STDERR,"[%s] Синхронизация папки почты · %s\n",$timestamp(),$error->errorCode);}}catch(Throwable$error){fprintf(STDERR,"[%s] Сбой синхронизации папки почты · %s\n",$timestamp(),get_class($error));$exit=1;}}}exit($exit);